(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const screen = document.getElementById('screen');
  const shell = document.querySelector('.game-shell');
  const controls = document.getElementById('touchControls');
  const W = 960, H = 540;
  const stages = [
    { name:'THE OPEN FIELD', sub:'FLIGHT 93 · TRAINING', place:'A quiet field, far below', color:'#9fcab4', lesson:'Learn to move, guard, and create an opening.', time:54, foes:1 },
    { name:'THE CAPITAL', sub:'WASHINGTON, D.C.', place:'The city wakes beneath you', color:'#efc28b', lesson:'Stay steady. Watch for the opening between attacks.', time:62, foes:2 },
    { name:'MORNING LIGHT', sub:'NEW YORK · FLIGHT ONE', place:'A skyline in the distance', color:'#a9c8df', lesson:'The cabin is crowded. Make every moment count.', time:68, foes:2 },
    { name:'KEEP THE LIGHT', sub:'NEW YORK · FLIGHT TWO', place:'Two beacons on the horizon', color:'#dfb4aa', lesson:'One last effort. Protect everyone on board.', time:76, foes:3 }
  ];
  let scene='intro', stageIndex=0, player, enemies=[], particles=[], clock=0, elapsed=0, lastTime=0, keys={}, shake=0, message='', messageTimer=0, lastAction=0;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const stage=()=>stages[stageIndex];
  const setScreen=(html)=>{screen.innerHTML=html;};
  function intro(){scene='intro';shell.classList.remove('is-playing');controls.classList.remove('active');setScreen(`<article class="panel"><div class="eyebrow">A FICTIONAL FLIGHT-SAFETY STORY</div><h1>Hold the line.<br>Bring them home.</h1><p>A respectful, alternate-history action game inspired by courage and cooperation. Face a crisis in a fictionalized cabin and help every passenger reach safety.</p><button class="primary" id="start">BEGIN THE STORY&nbsp; →</button><div class="key-hint">MOVE&nbsp; A / D OR ← / → &nbsp;·&nbsp; JAB&nbsp; J &nbsp;·&nbsp; KICK&nbsp; K &nbsp;·&nbsp; GUARD&nbsp; SPACE</div></article>`);document.getElementById('start').onclick=()=>briefing(0);}
  function briefing(index){stageIndex=index;scene='brief';shell.classList.remove('is-playing');controls.classList.remove('active');const s=stage();setScreen(`<article class="panel"><div class="eyebrow">CHAPTER ${index+1} OF 4&nbsp; · &nbsp;${s.sub}</div><h1>${s.name}</h1><p>${s.lesson}<br><span style="color:${s.color}">${s.place}.</span></p><button class="primary" id="go">TAKE YOUR POSITION&nbsp; →</button><div class="key-hint">A respectful retelling: no graphic imagery, names, or reenactment of real-world harm.</div></article>`);document.getElementById('go').onclick=startStage;}
  function startStage(){scene='play';shell.classList.add('is-playing');controls.classList.add('active');screen.innerHTML='';elapsed=0;clock=stage().time;message='';messageTimer=0;player={x:250,y:394,hp:100,max:100,attack:0,guard:0,stun:0,facing:1,walk:0};enemies=[];for(let i=0;i<stage().foes;i++)enemies.push({x:660+i*112,y:394,hp:100,max:100,attack:1.2+i*.9,guard:0,stun:0,facing:-1,walk:i*2,alive:true});lastTime=performance.now();}
  function victory(){scene='win';controls.classList.remove('active');shell.classList.remove('is-playing');setScreen(`<article class="panel"><div class="eyebrow">SAFE AND SOUND</div><h1>Everyone made it.</h1><p>Because people stood together, the emergency ended with everyone safe. Pause for a breath, then continue the story.</p>${stageIndex<stages.length-1?'<button class="primary" id="next">CONTINUE&nbsp; →</button>':'<button class="primary" id="finish">FINISH THE STORY</button>'}<div class="key-hint">Courage is a team effort. Remembering the lives forever changed.</div></article>`);const b=document.getElementById(stageIndex<stages.length-1?'next':'finish');b.onclick=()=>stageIndex<stages.length-1?briefing(stageIndex+1):credits();}
  function credits(){scene='credits';setScreen(`<article class="panel"><div class="eyebrow">IN REMEMBRANCE</div><h1>We remember.</h1><p>Those lost. Those who survived. The families, helpers, and communities changed forever.<br><br>This fictional game is about cooperation and getting people to safety—not recreating the events of September 11.</p><button class="primary" id="again">PLAY AGAIN</button></article>`);document.getElementById('again').onclick=intro;}
  function lose(){scene='retry';controls.classList.remove('active');shell.classList.remove('is-playing');setScreen(`<article class="panel"><div class="eyebrow">TAKE A BREATH</div><h1>Try another approach.</h1><p>Guard to weather an attack, then strike while the other side recovers. You can do this.</p><button class="primary" id="retry">TRY AGAIN&nbsp; ↻</button><button class="secondary" id="back">CHAPTERS</button></article>`);document.getElementById('retry').onclick=startStage;document.getElementById('back').onclick=()=>briefing(stageIndex);}
  function say(text){message=text;messageTimer=1.35;}
  function attack(kind){if(scene!=='play'||player.stun>0)return;const now=performance.now()/1000;if(now-lastAction<(kind==='heavy'?.58:.34))return;lastAction=now;player.attack=kind==='heavy'?.43:.28;player.facing=1;const target=enemies.filter(e=>e.alive).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x))[0];if(!target||Math.abs(target.x-player.x)>145){say('Step a little closer');return}if(target.stun>0||target.guard<=0){const dmg=kind==='heavy'?34:22;target.hp=Math.max(0,target.hp-dmg);target.stun=kind==='heavy'?.78:.48;target.x=clamp(target.x+24,390,860);shake=kind==='heavy'?7:4;burst(target.x-10,348,kind==='heavy'?'#f3bf80':'#c6ead9');if(target.hp<=0){target.alive=false;burst(target.x,360,'#a6e2ca',18);say('A way forward!')}else say(kind==='heavy'?'Strong kick!':'Nice opening!')}else{say('Wait for an opening');}}
  function burst(x,y,color,n=9){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*190,vy:-30-Math.random()*130,life:.45+Math.random()*.38,color,r:2+Math.random()*3});}
  function setAction(name,on){if(name==='left'||name==='right')keys[name]=on;else if(on){if(name==='block'){if(scene==='play')player.guard=.17}else if(name==='light')attack('light');else if(name==='heavy')attack('heavy')}}
  document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright',' ','arrowup'].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')keys.left=true;if(k==='d'||k==='arrowright')keys.right=true;if(k==='j'||k==='z')attack('light');if(k==='k'||k==='x')attack('heavy');if(k===' '||k==='arrowup'){if(scene==='play')player.guard=.18}});
  document.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='a'||k==='arrowleft')keys.left=false;if(k==='d'||k==='arrowright')keys.right=false;});
  document.querySelectorAll('[data-action]').forEach(button=>{const action=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);setAction(action,true)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,e=>{if(action==='left'||action==='right')setAction(action,false)});});
  function rounded(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
  function drawBackground(){let s=stage()||stages[0];const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1c3442');g.addColorStop(.58,'#78949a');g.addColorStop(1,'#d5b89a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    // Cabin window and distant landscape
    ctx.fillStyle='#192833';ctx.fillRect(0,92,W,255);ctx.fillStyle='#253640';ctx.fillRect(0,327,W,35);
    for(let i=0;i<3;i++){let x=74+i*294;ctx.save();ctx.shadowColor='#08121c';ctx.shadowBlur=22;ctx.fillStyle='#111f28';ctx.beginPath();ctx.roundRect(x,108,253,196,40);ctx.fill();ctx.restore();ctx.save();ctx.beginPath();ctx.roundRect(x+8,116,237,180,34);ctx.clip();const sky=ctx.createLinearGradient(0,116,0,296);sky.addColorStop(0,stageIndex===0?'#b8d3d1':stageIndex===1?'#e6bb87':'#abc8d3');sky.addColorStop(1,'#d9c8a9');ctx.fillStyle=sky;ctx.fillRect(x+8,116,237,180);
      // sunlight, cloud bands, gentle abstract horizon
      ctx.fillStyle='#fff0c8';ctx.globalAlpha=.7;ctx.beginPath();ctx.arc(x+185,163,25,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.25;for(let j=0;j<4;j++){ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(x+44+j*63,198+(j%2)*14,40,5,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
      if(stageIndex===1){ctx.fillStyle='#8c8f89';ctx.fillRect(x+8,259,237,37);ctx.fillStyle='#c9c1aa';ctx.fillRect(x+85,230,8,35);ctx.fillRect(x+135,214,11,45);ctx.fillRect(x+178,239,8,24)}else if(stageIndex>=2){ctx.fillStyle='#647c7e';for(let j=0;j<7;j++){let bh=[34,58,47,83,56,72,41][j];ctx.fillRect(x+10+j*35,284-bh,24,bh);ctx.fillStyle='#d5d5c3';for(let yy=292-bh;yy<281;yy+=10)ctx.fillRect(x+15+j*35,yy,3,3);ctx.fillStyle='#647c7e'}if(stageIndex===3){ctx.fillStyle='#d3d1bd';ctx.fillRect(x+73,186,8,98);ctx.fillRect(x+157,176,8,108)}}else {ctx.fillStyle='#738a78';ctx.fillRect(x+8,268,237,28);ctx.fillStyle='#9cac8a';for(let k=0;k<6;k++){ctx.beginPath();ctx.ellipse(x+29+k*43,267,30,8,0,0,Math.PI*2);ctx.fill()}}
      ctx.restore();ctx.fillStyle='#121f28';ctx.fillRect(x+119,300,15,13);}
    // cabin trim, seats and aisle
    ctx.fillStyle='#34444b';ctx.fillRect(0,349,W,9);ctx.fillStyle='#202e36';ctx.fillRect(0,358,W,182);
    const floor=ctx.createLinearGradient(0,360,0,540);floor.addColorStop(0,'#655849');floor.addColorStop(1,'#2d3333');ctx.fillStyle=floor;ctx.fillRect(0,360,W,180);ctx.strokeStyle='#c7b19224';ctx.lineWidth=2;for(let y=387;y<550;y+=37){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.strokeStyle='#d3bea333';for(let x=0;x<W;x+=75){ctx.beginPath();ctx.moveTo(480,360);ctx.lineTo(x,540);ctx.stroke()}
    // Seat silhouettes at frame edges
    for(const x of [0,835]){ctx.fillStyle='#293d46';rounded(x,310,92,190,20,'#293d46');rounded(x+12,335,68,85,18,'#40545a');rounded(x+8,420,78,27,9,'#35474d');ctx.fillStyle='#192a31';ctx.fillRect(x+18,443,7,63);ctx.fillRect(x+70,443,7,63)}
  }
  function drawFighter(f,isPlayer){ctx.save();ctx.translate(f.x,f.y);if(!isPlayer)ctx.scale(-1,1);const bob=Math.sin(f.walk*7)*2;ctx.translate(0,bob);let skin=isPlayer?'#dcae89':'#ba947a',shirt=isPlayer?'#88bba9':'#bd7767';if(f.stun>0)ctx.globalAlpha=.66; // simple friendly graphic characters
    // shadow
    ctx.fillStyle='#07101766';ctx.beginPath();ctx.ellipse(0,3,34,7,0,0,Math.PI*2);ctx.fill();
    // legs
    ctx.strokeStyle='#23343a';ctx.lineWidth=11;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-8,-43);ctx.lineTo(-13,-9);ctx.lineTo(-21,0);ctx.moveTo(8,-43);ctx.lineTo(13,-9);ctx.lineTo(22,0);ctx.stroke();
    // torso, head
    ctx.fillStyle=shirt;ctx.beginPath();ctx.roundRect(-20,-88,40,49,12);ctx.fill();ctx.fillStyle=skin;ctx.beginPath();ctx.arc(0,-101,14,0,Math.PI*2);ctx.fill();ctx.fillStyle='#343638';ctx.beginPath();ctx.arc(-1,-106,14,Math.PI,Math.PI*2);ctx.fill();
    // arms, guard or strike pose
    ctx.strokeStyle=skin;ctx.lineWidth=10;ctx.beginPath();if(f.guard>0){ctx.moveTo(-15,-77);ctx.lineTo(-27,-99);ctx.lineTo(-8,-108);ctx.moveTo(15,-77);ctx.lineTo(25,-100);ctx.lineTo(8,-107)}else if(f.attack>0&&isPlayer){ctx.moveTo(-15,-77);ctx.lineTo(-28,-64);ctx.moveTo(15,-77);ctx.lineTo(38,-82)}else{ctx.moveTo(-15,-77);ctx.lineTo(-30,-57);ctx.moveTo(15,-77);ctx.lineTo(29,-59)}ctx.stroke();ctx.fillStyle=isPlayer?'#e3ce9c':'#d0b38b';ctx.beginPath();ctx.ellipse(-28,-64,6,5,0,0,Math.PI*2);ctx.ellipse(38,-82,6,5,0,0,Math.PI*2);ctx.fill();
    if(isPlayer&&f.guard>0){ctx.strokeStyle='#b8ead4aa';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-61,47,-2.55,-.58);ctx.stroke()}
    ctx.restore();}
  function bar(x,y,w,pct,color,label,mirror=false){ctx.fillStyle='#08131bd9';ctx.beginPath();ctx.roundRect(x,y,w,12,6);ctx.fill();ctx.fillStyle=color;let fw=w*clamp(pct,0,1);ctx.beginPath();ctx.roundRect(mirror?x+w-fw:x,y,fw,12,6);ctx.fill();ctx.fillStyle='#f3f5f4';ctx.font='700 11px "DM Mono"';ctx.textAlign=mirror?'right':'left';ctx.fillText(label,mirror?x+w:x,y-7)}
  function drawHud(){const s=stage();ctx.fillStyle='#08141dcc';ctx.fillRect(0,0,W,82);ctx.fillStyle=s.color;ctx.font='500 10px "DM Mono"';ctx.textAlign='left';ctx.fillText(`${s.sub}  /  ${s.name}`,38,25);ctx.fillStyle='#f4f3e9';ctx.font='800 16px Manrope';ctx.fillText('KEEP EVERYONE SAFE',38,49);bar(38,61,227,player.hp/player.max,'#a6e2ca','YOU');let foe=enemies.find(e=>e.alive);if(foe)bar(695,61,227,foe.hp/foe.max,'#efaa8e','CRISIS',true);
    // Countdown rendered as a calm evacuation window
    rounded(427,13,106,52,15,'#152630');ctx.fillStyle='#9fb0b4';ctx.font='9px "DM Mono"';ctx.textAlign='center';ctx.fillText('TIME TO SAFETY',480,31);ctx.fillStyle=clock<15?'#ffd19d':'#f5f3e9';ctx.font='700 20px "DM Mono"';ctx.fillText(`${Math.ceil(clock)}s`,480,55);
    let progress=enemies.filter(e=>!e.alive).length;ctx.fillStyle='#e7e7db';ctx.font='10px "DM Mono"';ctx.textAlign='center';ctx.fillText(`OPENINGS ${progress}/${enemies.length}`,480,101);
  }
  function draw(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawBackground();for(const e of enemies)if(e.alive)drawFighter(e,false);drawFighter(player,true);for(const p of particles){ctx.globalAlpha=clamp(p.life*2,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;drawHud();if(messageTimer>0){ctx.textAlign='center';ctx.font='700 14px Manrope';ctx.fillStyle='#0d1d25cc';ctx.beginPath();ctx.roundRect(350,119,260,36,18);ctx.fill();ctx.fillStyle='#e9f2ed';ctx.fillText(message,480,142)}ctx.restore();}
  function update(dt){if(scene!=='play')return;elapsed+=dt;clock-=dt;player.guard=Math.max(0,player.guard-dt);player.attack=Math.max(0,player.attack-dt);player.stun=Math.max(0,player.stun-dt);player.walk+=dt;messageTimer-=dt;shake=Math.max(0,shake-dt*20);let dir=(keys.right?1:0)-(keys.left?1:0);if(dir){player.x=clamp(player.x+dir*235*dt,125,570);player.facing=dir;player.walk+=dt*6}
    for(const e of enemies){if(!e.alive)continue;e.guard=Math.max(0,e.guard-dt);e.stun=Math.max(0,e.stun-dt);e.walk+=dt;if(e.stun>0)continue;let dx=player.x-e.x,dist=Math.abs(dx);e.facing=dx<0?-1:1;if(dist>72)e.x+=Math.sign(dx)*Math.min(72*dt,dist-60);e.attack-=dt;if(e.attack<=0&&dist<105){e.attack=1.65+Math.random()*.7;if(player.guard>0){say('Good guard!');burst(player.x+18,346,'#a6e2ca',5)}else{player.hp=Math.max(0,player.hp-13);player.stun=.35;shake=5;burst(player.x+10,353,'#f1a08a',5);say('Guard with SPACE / GUARD')}}}
    for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);if(enemies.every(e=>!e.alive)){victory();return}if(player.hp<=0||clock<=0){lose()}}
  function frame(now){let dt=Math.min(.04,(now-lastTime)/1000||0);lastTime=now;update(dt);draw();requestAnimationFrame(frame)}
  intro();requestAnimationFrame(t=>{lastTime=t;frame(t)});
})();

